// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, address target, bytes calldata data, uint256 value) public {
        vm.assume(caller != c.Owner());
        vm.assume(target != address(c));
        value = bound(value, 0, address(c).balance);
        vm.deal(caller, value + 1 ether);
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        bool ok;
        try c.Command{value: value}(target, data) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
